def hidden_rule_fn(state):
    rows = len(state)
    cols = len(state[0])
    next_state = [[0] * cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            north = state[(r - 1) % rows][c]
            south = state[(r + 1) % rows][c]
            east = state[r][(c + 1) % cols]
            west = state[r][(c - 1) % cols]

            von_quad = [north, south, east, west]
            distinct = set(von_quad)
            D = len(distinct)
            current = state[r][c]

            if D == 1:
                next_state[r][c] = current
            elif D == 3:
                next_state[r][c] = (2 - current) % 3
            elif D == 2:
                # Count occurrences
                counts = {}
                for v in von_quad:
                    counts[v] = counts.get(v, 0) + 1
                max_count = max(counts.values())
                if max_count >= 3:
                    most_freq = [s for s in distinct if counts[s] == max_count][0]
                    next_state[r][c] = most_freq
                else:
                    # Tied: use min of distinct
                    next_state[r][c] = min(distinct)

    return next_state
